from django.db import migrations, models


def dedupe_active_instances(apps, schema_editor):
    """存量数据兜底：每条分支工程关联仅保留最新一条活跃实例，其余置为 STOPPED。

    保证 uniq_active_instance_per_branch_project 约束在存在历史脏数据时也能顺利施加。
    """
    Instance = apps.get_model("build_protection_service", "Instance")
    active_ids = list(
        Instance.objects.filter(status__in=("STARTING", "RUNNING"))
        .values_list("branch_project_id", "id")
        .order_by("branch_project_id", "-id")
    )
    seen = set()
    stale = []
    for bp_id, inst_id in active_ids:
        if bp_id in seen:
            stale.append(inst_id)
        else:
            seen.add(bp_id)
    if stale:
        Instance.objects.filter(id__in=stale).update(
            status="STOPPED", exit_code=0
        )


